"""Kiểm thử trình duyệt cho đợt A: landing brand.ai.vn, AI Health Check tự phục vụ (đăng ký → email → chạy → báo cáo),
biểu mẫu tư vấn, và tab Khách tiềm năng trong công cụ. Chạy:  npm run dev:fake   rồi   python3 test/ui-site.py"""
import asyncio, json, os, re, sys, urllib.request
from playwright.async_api import async_playwright
BASE = os.environ.get("BASE", "http://localhost:3100")
ok = True
def check(name, cond, extra=""):
    global ok
    print(("  ✓ " if cond else "  ✗ ") + name + ((" – " + str(extra)[:240]) if extra and not cond else "")); ok = ok and bool(cond)
def last_email():
    notify = os.environ.get("FAKE_NOTIFY")
    if not notify:
        log = open("/tmp/fake_site.log").read(); notify = re.search(r"Email/Telegram giả: (\S+)/last-email", log).group(1)
    return json.loads(urllib.request.urlopen(notify + "/last-email").read())
async def overflow(pg): return await pg.evaluate("document.documentElement.scrollWidth>document.documentElement.clientWidth+1")
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch(); errs = []
        ctx = await b.new_context(viewport={"width": 1300, "height": 900}); pg = await ctx.new_page(); pg.on('pageerror', lambda e: errs.append(str(e)))
        print("Landing")
        await pg.goto(BASE + "/site/home.html"); await pg.wait_for_timeout(600)
        check("landing có tiêu đề, dữ liệu có cấu trúc Organization/Service/FAQPage", await pg.evaluate("(()=>{const t=[...document.querySelectorAll('script[type=\"application/ld+json\"]')].map(s=>JSON.parse(s.textContent)).flat().map(x=>x['@type']);return ['Organization','Service','FAQPage'].every(k=>t.includes(k))})()"))
        check("nút Health Check trỏ tới /kiem-tra", await pg.evaluate("[...document.querySelectorAll('a')].filter(a=>a.getAttribute('href')==='/kiem-tra').length>=3"))
        print("Biểu mẫu tư vấn")
        await pg.click('#leadForm button[type=submit]'); await pg.wait_for_timeout(200)
        check("báo lỗi khi thiếu họ tên", "họ tên" in (await pg.inner_text('#leadForm .form-msg')))
        await pg.fill('#leadForm [name=name]', 'Anh Minh'); await pg.fill('#leadForm [name=company]', 'Công ty ABC'); await pg.fill('#leadForm [name=email]', 'minh@abc.vn')
        await pg.fill('#leadForm [name=phone]', '0912 345 678'); await pg.select_option('#leadForm [name=package]', 'AI Brand Audit'); await pg.check('#leadForm [name=consent]')
        await pg.click('#leadForm button[type=submit]'); await pg.wait_for_function("document.querySelector('#leadForm .form-msg').textContent.includes('Đã nhận')", timeout=10000)
        check("gửi yêu cầu tư vấn thành công", True)
        m = await ctx.new_page(); await m.set_viewport_size({"width": 390, "height": 800}); await m.goto(BASE + "/site/home.html"); await m.wait_for_timeout(500)
        check("landing trên điện thoại không tràn ngang", not await overflow(m))
        print("AI Health Check tự phục vụ")
        await pg.goto(BASE + "/site/kiem-tra.html"); await pg.wait_for_selector('#engines .chip')
        check("hiện các AI sẽ được hỏi", await pg.evaluate("document.querySelectorAll('#engines .chip').length") >= 3)
        await pg.fill('#hcForm [name=brand]', 'NetSpace'); await pg.fill('#hcForm [name=website]', 'http://127.0.0.1:3199'); await pg.fill('#hcForm [name=email]', 'khach@congty.vn')
        await pg.click('#hcForm button[type=submit]'); await pg.wait_for_timeout(200)
        check("chặn khi chưa đồng ý xử lý dữ liệu", "đồng ý" in (await pg.inner_text('#formMsg')))
        await pg.check('#hcForm [name=consent]'); await pg.click('#hcForm button[type=submit]')
        await pg.wait_for_selector('#stMail:not(.hidden)', timeout=10000)
        check("chuyển sang bước kiểm tra hộp thư", "khach@congty.vn" in await pg.inner_text('#stMail'))
        mail = last_email(); link = re.search(r"(/site/kiem-tra#v=[A-Za-z0-9_-]+)", mail["text"]).group(1)
        check("email xác minh gửi tới khách", mail["to"] == ["khach@congty.vn"])
        await pg.goto(BASE + link); await pg.wait_for_selector('#stRun:not(.hidden)')
        check("link trong email bị xóa khỏi thanh địa chỉ", "#v=" not in pg.url)
        await pg.wait_for_url(re.compile(r".*/site/report\.html\?t=.*"), timeout=90000)
        await pg.wait_for_selector('h2', timeout=10000); body = await pg.inner_text('main')
        check("báo cáo hiện tỷ lệ AI nhận ra, trích đoạn từng AI, kiểm tra kỹ thuật, 3 việc nên làm", all(x in body for x in ["AI nhận ra đúng thương hiệu", "AI đang nói gì về bạn", "Kiểm tra kỹ thuật website", "việc nên làm trước", "Claude", "ChatGPT"]), body[:300])
        check("báo cáo có nhãn tự động, chưa qua chuyên gia", "chưa qua chuyên gia" in body)
        mr = await ctx.new_page(); await mr.set_viewport_size({"width": 390, "height": 800}); await mr.goto(pg.url); await mr.wait_for_selector('h2', timeout=10000)
        check("báo cáo trên điện thoại không tràn ngang", not await overflow(mr)); await mr.screenshot(path='/tmp/site_report_m.png', full_page=True)
        await pg.screenshot(path='/tmp/site_report.png', full_page=True)
        print("Đợt B: PDF, hạn dùng")
        check("trang báo cáo có nút Tải PDF và dòng hạn dùng", await pg.is_visible('#pdf') and "hiệu lực đến" in body)
        await pg.emulate_media(media="print"); await pg.wait_for_timeout(200)
        check("bản in: nền trắng, ẩn thanh trên cùng và các nút", await pg.evaluate("getComputedStyle(document.body).backgroundColor==='rgb(255, 255, 255)'&&getComputedStyle(document.querySelector('.top')).display==='none'&&getComputedStyle(document.querySelector('#pdf')).display==='none'&&getComputedStyle(document.querySelector('.print-only')).display==='block'"))
        await pg.pdf(path='/tmp/site_report.pdf', format='A4'); await pg.emulate_media(media="screen")
        report_url = pg.url

        print("Khách tiềm năng trong công cụ")
        t = await ctx.new_page(); t.on('pageerror', lambda e: errs.append(str(e)))
        await t.goto(BASE + "/"); await t.wait_for_selector('#login:not([hidden]),#app:not([hidden])')
        if await t.evaluate("!document.querySelector('#login').hidden"):
            await t.fill('#lgEmail', 'staff@netspace.vn'); await t.fill('#lgPass', 'Mat-khau-1'); await t.click('#lgBtn')
        await t.wait_for_selector('#app:not([hidden])'); await t.wait_for_timeout(500)
        await t.click('#leadNav [data-tab="leads"]'); await t.wait_for_function("document.querySelector('#view').innerText.includes('Công ty ABC')", timeout=10000)
        v = await t.inner_text('#view')
        check("danh sách có lead từ biểu mẫu và từ Health Check", "Biểu mẫu tư vấn" in v and "Health Check" in v and "NetSpace" in v)
        hc_id = await t.evaluate("leadsState.list.find(l=>l.source==='health_check').id")
        await t.click(f'[data-act="leadOpen"][data-id="{hc_id}"]'); await t.wait_for_timeout(200)
        check("chi tiết lead có tóm tắt Health Check và link báo cáo", "AI Health Check" in await t.inner_text('#view') and await t.evaluate("!!document.querySelector('a[href*=\"/r/\"]')"))
        await t.select_option(f'[data-lead-status="{hc_id}"]', 'contacted'); await t.wait_for_timeout(500)
        check("đổi trạng thái lưu lên máy chủ", await t.evaluate(f"leadsState.list.find(l=>l.id==='{hc_id}').status") == 'contacted')
        await t.fill(f'[data-lead-note="{hc_id}"]', 'Đã gọi, hẹn demo thứ Hai'); await t.click(f'[data-act="leadNote"][data-id="{hc_id}"]'); await t.wait_for_timeout(500)
        check("lưu ghi chú nội bộ", await t.evaluate(f"leadsState.list.find(l=>l.id==='{hc_id}').staff_note") == 'Đã gọi, hẹn demo thứ Hai')
        await t.click(f'[data-act="leadAudit"][data-id="{hc_id}"]'); await t.wait_for_timeout(800)
        check("tạo audit từ lead: điền sẵn thương hiệu và website", await t.evaluate("A()&&A().profile.brand==='NetSpace'&&A().profile.website.startsWith('http://127.0.0.1')"))
        await t.wait_for_function("document.querySelector('#saveState').textContent==='Đã lưu'", timeout=10000)
        check("lead được gắn audit vừa tạo, chuyển trạng thái Audit", await t.evaluate(f"(()=>{{const l=leadsState.list.find(l=>l.id==='{hc_id}');return l.audit_id===cur&&l.status==='audit'}})()"))
        await t.click('#leadNav [data-tab="leads"]'); await t.wait_for_timeout(300)
        if not await t.evaluate(f"leadsState.open==='{hc_id}'"): await t.click(f'[data-act="leadOpen"][data-id="{hc_id}"]')
        await t.click('[data-act="leadsReload"]'); await t.wait_for_function("!leadsState.loading", timeout=10000); await t.wait_for_timeout(200)
        v2 = await t.inner_text('#view')
        check("lead hiện lượt xem báo cáo và hạn dùng", ("Khách đã mở" in v2 or "Khách chưa mở" in v2) and "hiệu lực đến" in v2)
        await t.click(f'[data-act="leadReport"][data-v="revoke"][data-id="{hc_id}"]'); await t.click(f'[data-act="leadReport"][data-v="revoke"][data-id="{hc_id}"]'); await t.wait_for_timeout(600)
        check("thu hồi đường dẫn (bấm 2 lần để xác nhận)", "đã thu hồi" in await t.inner_text('#view'))
        x = await ctx.new_page(); await x.goto(report_url); await x.wait_for_selector('h1')
        check("khách mở đường dẫn đã thu hồi thấy thông báo, không thấy dữ liệu", "thu hồi" in await x.inner_text('main') and "AI đang nói gì" not in await x.inner_text('main'))
        await t.click(f'[data-act="leadReport"][data-v="restore"][data-id="{hc_id}"]'); await t.wait_for_timeout(500)
        await t.click(f'[data-act="leadReport"][data-v="extend"][data-id="{hc_id}"]'); await t.wait_for_timeout(500)
        check("mở lại và gia hạn đường dẫn", "đã thu hồi" not in await t.inner_text('#view') and "Đã gia hạn" in await t.inner_text('#view'))
        check("link xem báo cáo từ công cụ không tính lượt xem (nv=1)", await t.evaluate("!!document.querySelector('a[href*=\"/r/\"][href$=\"?nv=1\"]')"))
        form_id = await t.evaluate("leadsState.list.find(l=>l.source==='form').id")
        check("quản trị viên thấy nút Xóa", await t.is_visible(f'[data-act="leadDelete"][data-id="{form_id}"]'))
        await t.click(f'[data-act="leadDelete"][data-id="{form_id}"]'); await t.wait_for_timeout(200)
        check("bấm lần 1 chỉ hỏi xác nhận, chưa xóa", await t.evaluate(f"leadsState.list.some(l=>l.id==='{form_id}')") and "Bấm lần nữa" in await t.inner_text(f'[data-act="leadDelete"][data-id="{form_id}"]'))
        await t.click(f'[data-act="leadDelete"][data-id="{form_id}"]'); await t.wait_for_timeout(600)
        check("bấm lần 2 xóa khỏi danh sách và máy chủ", not await t.evaluate(f"leadsState.list.some(l=>l.id==='{form_id}')") and "Đã xóa khách tiềm năng" in await t.inner_text('#view'))
        srv = await t.evaluate("fetch('/api/leads',{headers:{'X-ABR':'1'}}).then(r=>r.json()).then(j=>j.leads.map(l=>l.id))")
        check("máy chủ không còn lead đã xóa", form_id not in srv)
        tm = await ctx.new_page(); await tm.set_viewport_size({"width": 390, "height": 800}); await tm.goto(BASE + "/"); await tm.wait_for_selector('#app:not([hidden])'); await tm.wait_for_timeout(500)
        await tm.evaluate("tab='leads';renderAll()"); await tm.wait_for_timeout(600)
        check("tab Khách tiềm năng trên điện thoại không tràn ngang", not await overflow(tm))
        await t.goto(BASE + "/?lead=" + hc_id); await t.wait_for_selector('#app:not([hidden])'); await t.wait_for_timeout(800)
        check("link ?lead= trong thông báo mở thẳng lead đó", await t.evaluate(f"tab==='leads'&&leadsState.open==='{hc_id}'") and "lead=" not in t.url)
        check("không có lỗi JavaScript", not errs, errs)
        await b.close()
    print("\nTẤT CẢ ĐẠT" if ok else "\nCÓ LỖI"); sys.exit(0 if ok else 1)
asyncio.run(main())
